const body = $json.body ?? $json;
const prompt = body.prompt;
if (typeof prompt !== 'string' || !prompt.trim()) throw new Error('Request body must include a non-empty prompt string.');
if (prompt.trim().length > 4000) throw new Error('prompt must be at most 4000 characters.');
const requested = body.maxResults === undefined ? 5 : body.maxResults;
if (typeof requested !== 'number' || !Number.isInteger(requested) || requested < 1 || requested > 10) throw new Error('maxResults must be an integer from 1 to 10.');
return [{ json: { prompt: prompt.trim(), maxResults: requested } }];

const response = $input.first().json;
const results = Array.isArray(response.results) ? response.results : [];
const seen = new Set();
const seenUrls = new Set();
const docs = [];
for (const result of results) {
  if (typeof result.raw_content !== 'string' || !result.raw_content.trim() || result.raw_content.length > 500000) continue;
  if (typeof result.url !== 'string') continue;
  const source = result.url.trim().split('#', 1)[0];
  if (!/^https?:\/\/[^\s/?#@]+(?:[/?#]|$)/i.test(source) || /[\u0000-\u0020\u007f]/u.test(source)) continue;
  if (seenUrls.has(source)) continue;
  const text = result.raw_content.normalize('NFKC').replace(/\s+/gu, ' ').trim();
  if (!text) continue;
  if (seen.has(text)) continue;
  seen.add(text);
  seenUrls.add(source);
  docs.push({ text, file_source: source });
}
return [{json:{documents:docs, prompt:$('Validate prompt').first().json.prompt, found:docs.length}}];

const responses = $input.all();
const pages = $('Expand unique pages').all();
let queued = 0, alreadyPresent = 0;
const trackIds = [];
for (let i=0; i<responses.length; i++) {
  const r = responses[i].json;
  const code = Number(r.statusCode ?? 0);
  const body = r.body ?? {};
  const detail = typeof body.detail === 'string' ? body.detail : '';
  if (code >= 200 && code < 300) {
    if (body.status !== 'success' || typeof body.track_id !== 'string' || !body.track_id) throw new Error(`LightRAG returned an incomplete success for ${pages[i]?.json.file_source ?? 'a page'}: ${JSON.stringify(body)}`);
    queued++; trackIds.push(body.track_id); continue;
  }
  if (code === 409 && detail.startsWith('Document storage already contains')) { alreadyPresent++; continue; }
  throw new Error(`LightRAG rejected ${pages[i]?.json.file_source ?? 'a page'} (HTTP ${code}): ${detail || JSON.stringify(body)}`);
}
return [{json:{status:queued ? 'queued' : 'skipped',message:queued ? 'LightRAG accepted documents for background processing; ingestion is not complete yet.' : 'All usable sources were already present in LightRAG; no new processing was queued.',queued,alreadyPresent,trackIds}}];

// n8n Code node body: place directly after the Tavily HTTP Request node.
// Keeps accepted Tavily result objects unchanged for the existing dedup node.
const response = $input.first()?.json;
if (!response || typeof response !== 'object' || Array.isArray(response)) {
  throw new Error('Tavily returned a malformed response object.');
}
if (response.error !== undefined && response.error !== null && response.error !== '') {
  throw new Error(`Tavily search failed: ${String(response.error)}`);
}
if (!Array.isArray(response.results)) {
  throw new Error('Tavily response must contain a results array.');
}

const results = [];
const reasons = {};
const reject = (reason) => { reasons[reason] = (reasons[reason] ?? 0) + 1; };
const hasLetterOrNumber = /[\p{L}\p{N}]/u;
// These patterns only apply to short, stand-alone denial/error pages. They avoid
// rejecting useful articles that happen to discuss access errors.
const denialOnly = /^(?:access denied|access forbidden|403 forbidden|you have been blocked|request blocked|website unavailable|page unavailable|service unavailable|404 not found|page not found|this site can(?:not|\x27t) be reached|the site can(?:not|\x27t) be reached|robot check|captcha required|enable javascript and cookies to continue)[.!\s]*$/i;
for (const result of response.results) {
  if (!result || typeof result !== 'object' || Array.isArray(result)) { reject('malformed_result'); continue; }
  if (typeof result.raw_content !== 'string' || !result.raw_content.trim()) { reject('missing_raw_content'); continue; }
  if (result.raw_content.length > 500000) { reject('raw_content_too_large'); continue; }
  if (typeof result.url !== 'string') { reject('invalid_url'); continue; }
  const source = result.url.trim().split('#', 1)[0];
  if (!/^https?:\/\/[^\s/?#@]+(?:[/?#]|$)/i.test(source) || /[\u0000-\u0020\u007f]/u.test(source)) { reject('invalid_url'); continue; }
  const contentStart = result.raw_content.trimStart();
  if (/^(?:<!doctype\s+html\b|<html\b)/i.test(contentStart)) { reject('html_page'); continue; }
  const trimmed = result.raw_content.trim();
  if (!hasLetterOrNumber.test(trimmed)) { reject('no_alphanumeric_content'); continue; }
  if (trimmed.length <= 300 && denialOnly.test(trimmed)) { reject('access_denied_or_error_page'); continue; }
  results.push(result);
}
const rejected = Object.values(reasons).reduce((sum, count) => sum + count, 0);
return [{ json: { ...response, results, validation: { received: response.results.length, accepted: results.length, rejected, reasons } } }];

// n8n Code node body: place after the existing dedup node and before its IF node.
// Text and source values are copied verbatim because LightRAG uses them for identity.
const input = $input.first()?.json;
if (!input || typeof input !== 'object' || Array.isArray(input)) {
  throw new Error('Deduplication step returned a malformed document bundle.');
}
if (!Array.isArray(input.documents)) {
  throw new Error('Deduplication step must return a documents array.');
}
const validated = $('Validate search results').first()?.json;
if (!validated || !Array.isArray(validated.results)) {
  throw new Error('Validated search results are unavailable for metadata mapping.');
}
const stripFragment = (url) => url.split('#', 1)[0];
const metadataBySource = new Map();
for (const result of validated.results) {
  if (!result || typeof result.url !== 'string') continue;
  const source = stripFragment(result.url.trim());
  if (!metadataBySource.has(source)) {
    metadataBySource.set(source, {
      title: typeof result.title === 'string' && result.title.trim() ? result.title : undefined,
    });
  }
}
const seenSources = new Set();
const documents = input.documents.map((doc, index) => {
  if (!doc || typeof doc !== 'object' || typeof doc.text !== 'string' || !doc.text.trim() || typeof doc.file_source !== 'string' || !doc.file_source.trim()) {
    throw new Error(`Deduplicated document ${index} has invalid text/source alignment.`);
  }
  if (seenSources.has(doc.file_source)) {
    throw new Error(`Deduplicated documents contain a repeated source at index ${index}.`);
  }
  seenSources.add(doc.file_source);
  const match = metadataBySource.get(stripFragment(doc.file_source));
  return {
    ...doc,
    metadata: {
      source_url: doc.file_source,
      ...(match?.title ? { title: match.title } : {}),
      query: input.prompt,
      content_type: 'text/plain',
    },
  };
});
return [{ json: { ...input, found: documents.length, documents } }];
